using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Analytic.ExpRatioCM;

internal sealed class SeriesDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Exponential moments and their quotient coefficients.",
        H("Series and signed derivatives"), Blocks(
            Describe.Lean(DescribeId.Create("exp-ratio-weighted-series"),
                DeclarationHandle.Create("D5/S3/Analytic/ExpRatioCM/Series.weightedSeries"),
                H("Weighted exponential series"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The weighted series at order k is the sum of b(n)*n^k*exp(-n*t) over all natural n."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("exp-ratio-weighted-summability"),
                DeclarationHandle.Create("D5/S3/Analytic/ExpRatioCM/Series.summable_weighted"),
                H("Absolute convergence of weighted exponential series"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("If B>0 and abs(b(n))<=B^n for every natural n, then for every natural k and real t>log(B) the norms of b(n)*n^k*exp(-n*t) form a summable series."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exp-ratio-weighted-derivative"),
                DeclarationHandle.Create("D5/S3/Analytic/ExpRatioCM/Series.hasDerivAt_weighted"),
                H("The derivative of a weighted exponential series"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Under the same exponential coefficient bound, the order-k weighted series has derivative minus the order-(k+1) weighted series at every t>log(B). A summable uniform bound on a smaller half-line justifies differentiating the full series."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exp-ratio-reciprocal-identity"),
                DeclarationHandle.Create("D5/S3/Analytic/ExpRatioCM/Series.reciprocal_eq"),
                H("The reciprocal identity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive t, 1/(1-exp(-t)) is 1+1/(exp(t)-1). Both the positive-order equality and the zeroth-order constant shift use this identity."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exp-ratio-moment-summability"),
                DeclarationHandle.Create("D5/S3/Analytic/ExpRatioCM/Series.summable_expMoment"),
                H("Summability of exponential moments"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For natural i and positive t, the sequence (n+1)^i exp(-(n+1)t) is summable. The shifted Mathlib exponential-moment theorem supplies this result."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exp-ratio-iteratedderiv-f"),
                DeclarationHandle.Create("D5/S3/Analytic/ExpRatioCM/Series.iteratedDeriv_F"),
                H("Signed derivative composition"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For natural i and k and every real t, the k-th derivative of F(i) is (-1)^k F(i+k). The differentiation operation is iterated on globally defined functions."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exp-ratio-g-eq-f"),
                DeclarationHandle.Create("D5/S3/Analytic/ExpRatioCM/Series.G_eq_F"),
                H("Equality at positive orders"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For i at least one and t positive, G(i,t)=F(i,t). The reciprocal identity holds on a neighborhood of t, so its derivatives agree there."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exp-ratio-f-eq-tsum"),
                DeclarationHandle.Create("D5/S3/Analytic/ExpRatioCM/Series.F_eq_tsum"),
                H("The exponential moment expansion"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive t, F(i,t) is the sum over natural n of (n+1)^i exp(-(n+1)t). Polynomially weighted geometric convergence supplies locally uniform derivative bounds."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exp-ratio-f-pos"),
                DeclarationHandle.Create("D5/S3/Analytic/ExpRatioCM/Series.F_pos"),
                H("Strictly positive moments"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Every F(i,t) is strictly positive when t is positive. Each term in its convergent exponential expansion is positive."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exp-ratio-ratiog-eq-ratiof"),
                DeclarationHandle.Create("D5/S3/Analytic/ExpRatioCM/Series.ratioG_eq_ratioF"),
                H("Equality of positive-index ratios"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For i at least one and t positive, the ratios of the two derivative families agree."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exp-ratio-quotcoeff"),
                DeclarationHandle.Create("D5/S3/Analytic/ExpRatioCM/Series.quotCoeff"),
                H("The quotient coefficient recurrence"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The zeroth coefficient is one. At positive n the coefficient is (n+1)^(i+1) minus the sum over j from zero to n-1 of (j+2)^i times the coefficient at n-1-j."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("exp-ratio-quotcoeff-two"),
                DeclarationHandle.Create("D5/S3/Analytic/ExpRatioCM/Series.quotCoeff_two"),
                H("The second quotient coefficient"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every natural i, the coefficient at index two equals 2 times 3^i minus 4^i."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exp-ratio-coefficient-bound"),
                DeclarationHandle.Create("D5/S3/Analytic/ExpRatioCM/Series.abs_quotCoeff_le"),
                H("A geometric coefficient bound"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For B=2^(i+2), the absolute value of the n-th quotient coefficient is at most B^n. A weighted geometric convolution bounds the recursive contribution by B^n/3 and the numerator contribution by B^n/2."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exp-ratio-quotient-expansion"),
                DeclarationHandle.Create("D5/S3/Analytic/ExpRatioCM/Series.ratioF_eq_tsum"),
                H("The quotient expansion"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For t greater than log(2^(i+2)), the first ratio equals the sum of b(n) exp(-nt). The absolutely convergent Cauchy product reduces this identity to the coefficient recurrence, and the denominator is positive."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("exp-ratio-quotient-derivatives"),
                DeclarationHandle.Create("D5/S3/Analytic/ExpRatioCM/Series.iteratedDeriv_ratioF"),
                H("Signed derivatives of the quotient expansion"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive k and t greater than log(2^(i+2)), the signed k-th derivative of the first ratio equals the sum of b(n) n^k exp(-nt). Exponential coefficient bounds provide a summable local majorant at every derivative order."))), DescribeRole.Theorem))));
}
